   "module": "shuliang",
   "q": "某抗洪指挥部的所有人员中，有23的人在前线指挥抢险。由于汛情紧急，又增派6 人前往，此时在前线指挥抢险的人数占总人数的75%。如该抗洪指挥部需要保留至少10%的人员在应急指挥中心，那么最多还能再增派多少人去前线（ ）",
