   "q": "某集团企业5 个分公司分别派出1 人去集团总部参加培训，培训后再将5 人随机分配到这5 个分公司，每个分公司只分配1 人。问5 个参加培训的人中，有且仅有1 人在培训后返回原分公司的概率（ ）",
