   "answer": 2,
   "explain": "】工程问题。根据题意，赋值总量为时间最小公倍数60，则全部5 条的效率为12， 2×2 ＝15天。 最快的3 条生产线效率和为10，则最慢的两条生产线的效率和为：12－10＝2。当产 60 能扩大一倍时，时间＝ 故正确答案为C。",
