   "module": "shuliang",
   "q": "某次军事演习中，一架无人机停在空中对三个地面目标点进行侦察。已知三个目标点在地面上的连线为直角三角形，两个点之间的最远距离为600 米。问无人机与三个点同时保持500 米距离时，其飞行高度为多少米（ ）全国服务电话：400-6353-6062312",
