   "answer": 3,
   "explain": "】几何问题。根据题意作上图，飞机P 的投影点O 与三个顶点A、B、C 的距离也相 同。因任意直角三角形中，斜边中点距离三个顶点距离相同，所以投影点为斜边中点， PO＝√PC × PC −OC × OC＝√500 × 500 −300 × 300＝400米。 所以OC 长度为最远两点AB（600 米）的一半，即OC＝300 米；在直角三角形POC 中， 故正确答案为D。 P B A C 第四部分 判断推理",
